/**
 * One Door — one-link digital presence cards.
 *
 * A One Door card is a single self-contained page that works as a digital
 * business card, a Linktree-style link hub, a musician EPK, or a one-page
 * presence for a preacher without a website. The maker takes a person's
 * details and renders the finished page; the API route in
 * src/app/api/one-door stores it and (optionally) publishes it to Vercel.
 *
 * This module is pure TypeScript: no I/O, no secrets, no network. It is
 * safe to import from server routes. QR codes are generated by the API
 * route (qrcode package) and passed in as data URLs.
 */

/** Product name — the single source of truth. Change it here and
 *  the card pages, the maker panel, and the site header follow. */
export const PRODUCT_NAME = "One Door";

export type OneDoorLinkKind =
  | "website"
  | "social"
  | "music"
  | "video"
  | "booking"
  | "sermon"
  | "giving"
  | "other";

export type OneDoorTemplate = "business" | "linkhub" | "musician" | "preacher";

export type OneDoorLink = {
  id: string;
  label: string;
  url: string;
  kind: OneDoorLinkKind;
};

export type OneDoorProfile = {
  name: string;
  roles: string[];
  tagline?: string;
  bio?: string;
  /** data:image/jpeg|png|webp;base64,... — never a remote URL, never a secret. */
  photoDataUrl?: string;
  /** Brand mark or monogram shown at the top of the card. Same rules as the photo. */
  logoDataUrl?: string;
  phone?: string;
  email?: string;
  /** Phone and email are published ONLY when the matching flag is true.
      The panel asks before turning either on. */
  showPhone: boolean;
  showEmail: boolean;
  links: OneDoorLink[];
  template: OneDoorTemplate;
};

export type OneDoorCardMeta = {
  id: string;
  slug: string;
  name: string;
  template: OneDoorTemplate;
  createdAt: string;
  updatedAt: string;
  /** Public Vercel URL once published; empty until then. */
  publishedUrl: string;
};

export type OneDoorCardRecord = OneDoorCardMeta & {
  profile: OneDoorProfile;
};

export const ONE_DOOR_LIMITS = {
  nameMax: 80,
  rolesMax: 5,
  roleMax: 40,
  taglineMax: 160,
  bioMax: 280,
  linksMax: 12,
  linkLabelMax: 40,
  phoneMax: 30,
  emailMax: 120,
  photoMaxBytes: 2_000_000,
  logoMaxBytes: 2_000_000,
  requestMaxBytes: 3_500_000,
} as const;

export const ONE_DOOR_LINK_KINDS: OneDoorLinkKind[] = [
  "website",
  "social",
  "music",
  "video",
  "booking",
  "sermon",
  "giving",
  "other",
];

export const ONE_DOOR_TEMPLATES: OneDoorTemplate[] = [
  "business",
  "linkhub",
  "musician",
  "preacher",
];

