/* ------------------------------------------------------------------ */
/* small helpers                                                       */
/* ------------------------------------------------------------------ */

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function escapeAttr(value: string): string {
  return escapeHtml(value);
}

export function slugifyName(name: string): string {
  const slug = name
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  return slug || "card";
}

export function cardSlug(name: string, id: string): string {
  return `${slugifyName(name)}-${id.slice(0, 8)}`;
}

export function initialsFor(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  const first = parts[0]?.[0] || "M";
  const last = parts.length > 1 ? parts[parts.length - 1][0] : "";
  return (first + last).toUpperCase();
}

function isHttpUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

function vcardEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
}

/**
 * JSON-encode a value for embedding inside an inline <script> block.
 * JSON.stringify alone does NOT escape <, >, or & — a name containing
 * "</script>" would break out of the script element. Unicode-escaping
 * those three characters keeps the JSON valid and the page safe.
 */
function jsonForScript(value: string): string {
  return JSON.stringify(value).replace(/</g, "\\u003c").replace(/>/g, "\\u003e").replace(/&/g, "\\u0026");
}

/* ------------------------------------------------------------------ */
/* validation                                                          */
/* ------------------------------------------------------------------ */

export type OneDoorValidation =
  | { ok: true; profile: OneDoorProfile }
  | { ok: false; errors: string[] };

export function validateProfile(input: unknown): OneDoorValidation {
  const errors: string[] = [];
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, errors: ["Card details are missing."] };
  }
  const value = input as Record<string, unknown>;
  const asString = (field: string): string =>
    typeof value[field] === "string" ? (value[field] as string).trim() : "";

  const name = asString("name");
  if (!name) errors.push("A name is required.");
  if (name.length > ONE_DOOR_LIMITS.nameMax) errors.push("Name is too long.");

  const rawRoles = value.roles;
  const roles: string[] = Array.isArray(rawRoles)
    ? rawRoles.filter((r): r is string => typeof r === "string").map(r => r.trim()).filter(Boolean)
    : [];
  if (roles.length < 1) errors.push("Add at least one role (what this person does).");
  if (roles.length > ONE_DOOR_LIMITS.rolesMax) errors.push("Keep it to five roles at most.");
  if (roles.some(r => r.length > ONE_DOOR_LIMITS.roleMax)) errors.push("Each role must be short.");

  const tagline = asString("tagline");
  if (tagline.length > ONE_DOOR_LIMITS.taglineMax) errors.push("Tagline is too long.");
  const bio = asString("bio");
  if (bio.length > ONE_DOOR_LIMITS.bioMax) errors.push("Bio is too long.");

  const template = asString("template") as OneDoorTemplate;
  const safeTemplate: OneDoorTemplate = (ONE_DOOR_TEMPLATES as string[]).includes(template)
    ? template
    : "business";

  const phone = asString("phone");
  const email = asString("email");
  const showPhone = value.showPhone === true;
  const showEmail = value.showEmail === true;
  if (phone.length > ONE_DOOR_LIMITS.phoneMax) errors.push("Phone number is too long.");
  if (phone && !/^[+()\-.\s\d]+$/.test(phone)) errors.push("Phone number looks invalid.");
  if (email.length > ONE_DOOR_LIMITS.emailMax) errors.push("Email address is too long.");
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push("Email address looks invalid.");
  if (showPhone && !phone) errors.push("Turned on showing the phone number, but no phone number was given.");
  if (showEmail && !email) errors.push("Turned on showing the email address, but no email address was given.");

  const rawLinks = value.links;
  const links: OneDoorLink[] = [];
  if (rawLinks !== undefined) {
    if (!Array.isArray(rawLinks)) {
      errors.push("Links must be a list.");
    } else {
      if (rawLinks.length > ONE_DOOR_LIMITS.linksMax) errors.push("Keep it to twelve links at most.");
      rawLinks.forEach((item, index) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          errors.push(`Link ${index + 1} is not valid.`);
          return;
        }
        const link = item as Record<string, unknown>;
        const label = typeof link.label === "string" ? link.label.trim() : "";
        const url = typeof link.url === "string" ? link.url.trim() : "";
        const kind = typeof link.kind === "string" ? link.kind : "other";
        if (!label) errors.push(`Link ${index + 1} needs a label.`);
        if (label.length > ONE_DOOR_LIMITS.linkLabelMax) errors.push(`Link ${index + 1} label is too long.`);
        if (!url || !isHttpUrl(url)) errors.push(`Link ${index + 1} needs a full web address starting with http.`);
        links.push({
          id: typeof link.id === "string" && link.id ? link.id : `link-${index + 1}`,
          label,
          url,
          kind: (ONE_DOOR_LINK_KINDS as string[]).includes(kind) ? (kind as OneDoorLinkKind) : "other",
        });
      });
    }
  }

  let photoDataUrl: string | undefined;
  const rawPhoto = value.photoDataUrl;
  if (typeof rawPhoto === "string" && rawPhoto) {
    const match = /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(rawPhoto.trim());
    if (!match) {
      errors.push("Photo must be a JPEG, PNG, or WebP image.");
    } else {
      const bytes = Math.floor((match[2].length * 3) / 4);
      if (bytes > ONE_DOOR_LIMITS.photoMaxBytes) errors.push("Photo is too large. Keep it under 2 MB.");
      else photoDataUrl = rawPhoto.trim();
    }
  }

  let logoDataUrl: string | undefined;
  const rawLogo = value.logoDataUrl;
  if (typeof rawLogo === "string" && rawLogo) {
    const match = /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(rawLogo.trim());
    if (!match) {
      errors.push("Logo must be a JPEG, PNG, or WebP image.");
    } else {
      const bytes = Math.floor((match[2].length * 3) / 4);
      if (bytes > ONE_DOOR_LIMITS.logoMaxBytes) errors.push("Logo is too large. Keep it under 2 MB.");
      else logoDataUrl = rawLogo.trim();
    }
  }

  if (errors.length > 0) return { ok: false, errors };
  return {
    ok: true,
    profile: {
      name,
      roles,
      tagline: tagline || undefined,
      bio: bio || undefined,
      photoDataUrl,
      logoDataUrl,
      phone: phone || undefined,
      email: email || undefined,
      showPhone,
      showEmail,
      links,
      template: safeTemplate,
    },
  };
}

/* ------------------------------------------------------------------ */
/* vCard                                                               */
/* ------------------------------------------------------------------ */

export function buildVCard(profile: OneDoorProfile): string {
  const lines = ["BEGIN:VCARD", "VERSION:3.0", `FN:${vcardEscape(profile.name)}`];
  if (profile.roles.length > 0) lines.push(`TITLE:${vcardEscape(profile.roles.join(", "))}`);
  if (profile.showPhone && profile.phone) lines.push(`TEL;TYPE=CELL:${vcardEscape(profile.phone)}`);
  if (profile.showEmail && profile.email) lines.push(`EMAIL:${vcardEscape(profile.email)}`);
  const website = profile.links.find(l => l.kind === "website");
  if (website) lines.push(`URL:${vcardEscape(website.url)}`);
  if (profile.tagline) lines.push(`NOTE:${vcardEscape(profile.tagline)}`);
  lines.push("END:VCARD");
  return lines.join("\r\n") + "\r\n";
}

/* ------------------------------------------------------------------ */
/* card page rendering                                                 */
/* ------------------------------------------------------------------ */

/** Show a link address the way the card does: host plus path, no scheme. */
function displayUrl(value: string): string {
  try {
    const url = new URL(value);
    return url.host + (url.pathname === "/" ? "" : url.pathname);
  } catch {
    return value.replace(/^https?:\/\//, "");
  }
}

